// ============================================================
// TILE: Serie temporal (intervalo 1 dia) del conteo de documentos creados a lo largo del tiempo, separados por tipo (dashboard / notebook).
// IMPORTANTE: Este tablero SOLO es usable despues de generar el
//             lookup table "/lookups/documents_report" con el
//             censo (senso) de los documents.
// ============================================================
load "/lookups/documents_report" 

| filter in(type, array($type))
| fields 
    type, 
    timestamp = toTimestamp(modificationInfo[createdTime])
| makeTimeseries 
    count = count(), 
    by: { type}, 
    interval: $timeshift:noquote

// ------------------------------------------------------------
// Creado por: Jose Romero | jose.romero@dynatrace.com | 18 dic 2025
// ------------------------------------------------------------

