4.query:
// ============================================================
// TILE: Tabla: documentos duplicados detectados por el patron de nombre 'Copy of'. Agrupa cada copia con su documento base y muestra el conteo de repeticiones, nombres e IDs.
// IMPORTANTE: Este tablero SOLO es usable despues de generar el
//             lookup table "/lookups/documents_report" con el
//             censo (senso) de los documents.
// ============================================================
load "/lookups/documents_report" 

| filter in(type, array($type))
| fieldsAdd match_case_original = lower(name) 
| fieldsAdd match_case_copy = array($documents_copy) 
| filter iAny( contains(lower(name), splitString(match_case_copy[], "|")[0])) 

| fieldsAdd duplicated_id = if(contains(lower(name), splitString(match_case_copy[], "|")[0]), splitString(match_case_copy[], "|")[1]) 
| fieldsAdd duplicated_name = if(contains(lower(name), splitString(match_case_copy[], "|")[0]), splitString(match_case_copy[], "|")[0]) 

| fieldsAdd duplicated_id = toUid(arraySort(duplicated_id)[0]) 
| fieldsAdd duplicated_name = arraySort(duplicated_name)[0] 

| summarize id = collectDistinct(id), name = collectDistinct(name), repeated = count(), by: { duplicated_id, duplicated_name, type} 

| filter repeated > 1 
| sort repeated desc 
| fields 
    `Document Type` = type, 
    `Repeated Count` = repeated, 
    `Base document name` = duplicated_name, 
    `List Document name` = arrayToString(name, delimiter:"\n") , 
    `List Document id` = arrayToString(id, delimiter:"\n")


// ------------------------------------------------------------
// Creado por: Jose Romero | jose.romero@dynatrace.com | 18 dic 2025
// ------------------------------------------------------------

